head.script:
scwin.screenId = "jldstf30006";

///////// 1. 변수 및 선언 영역 /////////

scwin.grd_Grid = $c.util.getComponent('grd_Grid');

scwin.panel_msg = $c.util.getComponent('panel_msg');

scwin.vScrenID = 'ULDSTF30006.gfm';


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.fn_SetCode();
        scwin.resizeToWin();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_SCHEDULE = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_SCHEDULE')) : $c.util.getComponent('dts_SCHEDULE');

scwin.dts_schelAdmBas = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsSchelAdmBas')) : $c.util.getComponent('dtsSchelAdmBas');

scwin.vUsrId = undefined; try { scwin.vUsrId = /* sdd-asis-lifecycle:begin vUsrId — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("id")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

scwin.vUsrTpCd = undefined; try { scwin.vUsrTpCd = /* sdd-asis-lifecycle:begin vUsrTpCd — as-is 원문 본문(전환 이관 · 포팅 적용됨) */js_usr_tp_cd/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

scwin.gLdMktTp = undefined; try { scwin.gLdMktTp = /* sdd-asis-lifecycle:begin gLdMktTp — as-is 원문 본문(전환 이관 · 포팅 적용됨) */$c.session.getUserInfo("market")/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

scwin.gParamObj = undefined; try { scwin.gParamObj = /* sdd-asis-lifecycle:begin gParamObj — as-is 원문 본문(전환 이관 · 포팅 적용됨) */new Array(4)/* sdd-asis-lifecycle:end */; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30006' }); }

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf30006.onpageload' });
    }
};


