/**
 * @event
 * @name scwin.grd_Grid_ondblclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param row colid
 * @returns
 * @hidden N
*/
scwin.grd_Grid_ondblclick = function (row, colid) {
    try {
        /* sdd-asis-lifecycle:begin grd_Grid_ondblclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (colid === "X_PATH_NM") {
            if (scwin.dts_SCHEDULE.getCellData(row, "DISCLS_SCHDL_ADM_BAS_TP_CD") === '01') {
                scwin.openForm(scwin.dts_SCHEDULE.getCellData(row, "REAL_FORM_CD"), scwin.dts_SCHEDULE.getCellData(row, "REAL_FORM_VER"), $c.fil.getObjectValue(slc_cmb_DEP_CD), scwin.dts_SCHEDULE.getCellData(row, "X_PATH"), scwin.dts_SCHEDULE.getCellData(row, "SCHDL_ADM_ITM_TP_NM"));
            }
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30006.grd_Grid_ondblclick' }); }
};

/**
 * @event
